referenceSolutions.javascript:
export function validAnagram(first, second) {
  if (first.length !== second.length) return false;
  const counts = new Map();
  for (const letter of first) counts.set(letter, (counts.get(letter) ?? 0) + 1);
  for (const letter of second) {
    const count = counts.get(letter) ?? 0;
    if (count === 0) return false;
    counts.set(letter, count - 1);
  }
  return true;
}

referenceSolutions.typescript:
export function validAnagram(first: string, second: string): boolean {
  if (first.length !== second.length) return false;
  const counts = new Map<string, number>();
  for (const letter of first) counts.set(letter, (counts.get(letter) ?? 0) + 1);
  for (const letter of second) {
    const count = counts.get(letter) ?? 0;
    if (count === 0) return false;
    counts.set(letter, count - 1);
  }
  return true;
}
